extension ShapeStyle where Self == Color {
    /// The page.
    public static var page: Color { Made.background }
    /// A plane over the page: a sheet, a card, a bar.
    public static var surface: Color { Made.surface }
    /// The faintest step a container takes off the page.
    public static var containerLowest: Color { Made.containerLowest }
    /// A container one step off the page.
    public static var containerLow: Color { Made.containerLow }
    /// A container: a field, a grouped list's rows.
    public static var container: Color { Made.container }
    /// A container a step further: a chip, a track.
    public static var containerHigh: Color { Made.containerHigh }
    /// The furthest step: a pressed row, a meter's track.
    public static var containerHighest: Color { Made.containerHighest }
    /// The fill of a glass chip, menu and sheet.
    public static var glassFill: Color { Made.glass }
    /// The edge of a control: a field, an unchecked box.
    public static var outline: Color { Made.outline }
    /// A divider, and a cover's edge.
    public static var hairline: Color { Made.hairline }
    /// Text.
    public static var ink: Color { Made.ink }
    /// Secondary text: a subtitle, a count, a caption.
    public static var quiet: Color { Made.quiet }
    /// What cannot be pressed.
    public static var disabled: Color { Made.disabled }
    /// What dims the page under a dialog.
    public static var scrim: Color { Made.scrim }
    /// A snackbar: the other side's surface.
    public static var inverseSurface: Color { Made.inverseSurface }
    /// Text on the inverse surface.
    public static var inverseInk: Color { Made.inverseInk }
    /// Wrong: an error, an overspent amount.
